// Client routes and bot commands in English, former French names kept as DURABLE aliases
// (old links in the Telegram history, bookmarks). Routes: same view under both names, URL
// replaced by the English name with its query and fragment; links generated by the server
// point to the English names. Bot: old commands, same arguments, same reply; menu in English,
// descriptions in the instance locale; callback_data unchanged.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { clientBundle } from './client-render.js'
import { createBot, COMMAND_NAMES, COMMAND_ALIASES } from '../lib/notify/bot.js'
import { setLocale } from '../lib/i18n.js'

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
// former French names, frozen: each must stay served (never removed from the alias table)
export const FRENCH_ROUTES = { '/alertes': '/alerts', '/reseau': '/network', '/sauvegardes': '/backups', '/maj': '/updates', '/mural': '/wall' }
export const FRENCH_COMMANDS = { reseau: 'network', appareil: 'device', connu: 'known' }

const app = t => clientBundle(t, 'p5f-routes', [
  "import { renderToStaticMarkup } from 'react-dom/server'",
  "import { prerender } from 'react-dom/static'",
  "import { createElement as h } from 'react'",
  "import { Router } from 'wouter'",
  "import { QueryClient, QueryClientProvider } from '@tanstack/react-query'",
  "import App from './src/App.jsx'",
  "import { AdminProvider } from './src/admin.jsx'",
  "import { VIEWS } from './src/nav.js'",
  "export { LEGACY_ROUTES, canonicalUrl } from './src/lib/routes.js'",
  'export { VIEWS }',
  'const tree = path => {',
  '  const qc = new QueryClient({ defaultOptions: { queries: { retry: false, enabled: false } } })',
  '  qc.setQueryData(["session"], { admin: false, anonymousRead: true, configured: true, networkAllowed: true })',
  '  qc.setQueryData(["config"], { title: "Banc" })',
  '  return h(QueryClientProvider, { client: qc }, h(Router, { ssrPath: path }, h(AdminProvider, null, h(App))))',
  '}',
  // lazy views loaded by a first render that waits for them, then a full synchronous render
  'export async function render(path) {',
  '  await new Response((await prerender(tree(path))).prelude).text()',
  '  return renderToStaticMarkup(tree(path))',
  '}',
])

test('routes: each former French name has its alias to the English name (frozen table, never reduced)', async t => {
  const c = await app(t)
  if (!c) return
  for (const [old, to] of Object.entries(FRENCH_ROUTES)) assert.equal(c.LEGACY_ROUTES[old], to, `${old} without alias`)
  assert.deepEqual(Object.keys(c.LEGACY_ROUTES).sort(), Object.keys(FRENCH_ROUTES).sort())
  // navigation uses only the English names now
  assert.deepEqual(c.VIEWS.map(v => v.path).filter(p => Object.hasOwn(FRENCH_ROUTES, p)), [])
})

test('routes: English URL of a former name, query and fragment kept; English or unknown name: nothing', async t => {
  const c = await app(t)
  if (!c) return
  assert.equal(c.canonicalUrl('/reseau', 'd=12&env=prod', '#carte'), '/network?d=12&env=prod#carte')
  assert.equal(c.canonicalUrl('/reseau', '?d=12', ''), '/network?d=12')
  assert.equal(c.canonicalUrl('/alertes', '', ''), '/alerts')
  assert.equal(c.canonicalUrl('/maj', 'q=Debian', '#'), '/updates?q=Debian')
  assert.equal(c.canonicalUrl('/sauvegardes', '', 'x'), '/backups#x')
  assert.equal(c.canonicalUrl('/mural', 'env=prod', ''), '/wall?env=prod')
  for (const p of ['/network', '/alerts', '/', '/services', '/infra', '/inconnu', '/toString', '/__proto__']) assert.equal(c.canonicalUrl(p, 'a=1', '#b'), null, p)
  // App replaces the URL (without a history entry) with this result, with the browser fragment
  const src = fs.readFileSync(path.join(ROOT, 'client/src/App.jsx'), 'utf8')
  assert.match(src, /const to = canonicalUrl\(location, search, window\.location\.hash\)\n\s+if \(to\) navigate\(to, \{ replace: true \}\)/)
})

test('routes: same view under the former name and under the English name (full application, views loaded)', async t => {
  const c = await app(t)
  if (!c) return
  // the view (<main> element, or the whole page for the wall display, outside the frame); the active
  // navigation link lights up only once the URL has been replaced by the English name
  const MARK = { '/alerts': 'Alertes actives', '/network': 'Appareils du LAN', '/backups': 'Sauvegardes', '/updates': 'Mises à jour', '/wall': 'Banc' }
  const view = html => html.match(/<main\b[\s\S]*<\/main>/)?.[0] ?? html
  for (const [old, to] of Object.entries(FRENCH_ROUTES)) {
    const [a, b] = [view(await c.render(old)), view(await c.render(to))]
    assert.doesNotMatch(b, /Page introuvable|Chargement de la vue/, to)
    assert.ok(b.includes(MARK[to]), `${to}: view rendered (${MARK[to]})`)
    assert.equal(a, b, `${old} and ${to}`)
  }
  assert.match(await c.render('/inconnu'), /Page introuvable/)
})

test('generated links: the server no longer produces any former page name (Telegram, digest, alerts, buttons)', () => {
  let out = ''
  try {
    out = execFileSync('git', ['grep', '-nE', "['\"`]/(alertes|reseau|sauvegardes|maj|mural)\\b", '--', 'server/lib', 'server/plugins', 'server/index.js', 'server/scripts', 'client/src'], { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })
  } catch (e) {
    if (e.status !== 1) throw e // 1: no match
  }
  const hits = out.split('\n').filter(Boolean).filter(l => !l.startsWith('client/src/lib/routes.js:'))
  assert.deepEqual(hits, [])
  const golden = ['telegram.txt', 'network.txt', 'digest.txt', 'notify-cycle.txt', 'rules-extra.txt'].map(f => fs.readFileSync(path.join(ROOT, 'server/test/golden', f), 'utf8')).join('\n')
  assert.doesNotMatch(golden, /example\.net\/(alertes|reseau|sauvegardes|maj|mural)\b/)
  assert.match(golden, /example\.net\/network\?d=\d+/)
})

function bench({ network } = {}) {
  const sent = []
  let commands = null
  const telegram = { configured: true, chatId: '42', send: async t => (sent.push(t), { message_id: sent.length }), setCommands: async c => { commands = c }, getUpdates: async () => new Promise(() => {}), answerCallback: async () => {} }
  const acks = []
  const writes = { ack: ({ ids, reason }) => (acks.push([ids, reason]), { done: ids }) }
  const net = network ?? {
    enabled: true, writes,
    view: () => ({ presence: 'arp', counts: { total: 2, online: 1, offline: 1, new: 1, review: 0 }, sources: { arp: { ok: true } }, presenceSince: 1, devices: [] }),
    search: q => ({ total: 1, devices: [{ id: 12, name: `résultat ${q}`, ip: '192.0.2.12', mac: '00:00:5e:00:53:12', state: 'known', freshness: 'active' }] }),
  }
  const bot = createBot({ telegram, store: { kv: { get: () => '1', set() {} } }, cfg: { hosts: [], services: [], alerts: { timezone: 'Europe/Paris' } }, engine: { active: () => [], byIncident: () => null, get: () => null }, silences: { active: () => [] }, refresher: {}, audit: { log() {}, refused() {} }, clock: { hm: () => '10:00' }, texts: { status: () => 'ok' }, allowedIds: '7', network: net, log: { warn() {}, error() {} } })
  const say = text => bot.handle({ update_id: 1, message: { message_id: 9, text, from: { id: 7 }, chat: { id: 42 } } }).then(() => sent.at(-1))
  return { bot, sent, acks, say, commands: () => commands }
}

test('bot: each former French command, same arguments, same reply as the English command', async () => {
  assert.deepEqual(COMMAND_ALIASES, FRENCH_COMMANDS)
  for (const [old, neu] of Object.entries(FRENCH_COMMANDS)) assert.ok(COMMAND_NAMES.includes(neu), neu)
  const b = bench()
  for (const [oldCmd, newCmd] of [['/reseau', '/network'], ['/appareil galaxy', '/device galaxy'], ['/connu 12 téléphone prêté', '/known 12 téléphone prêté'], ['/appareil', '/device'], ['/connu', '/known'], ['/reseau@vigie_bot', '/network@vigie_bot']]) {
    const [a, n] = [await b.say(oldCmd), await b.say(newCmd)]
    assert.equal(a, n, `${oldCmd} / ${newCmd}`)
    assert.doesNotMatch(n, /Commande inconnue/, newCmd)
  }
  assert.deepEqual(b.acks, [[[12], 'téléphone prêté'], [[12], 'téléphone prêté']], 'same write through both names')
})

test('bot: menu in English (names), descriptions in the instance locale; help with the new names and the former ones accepted', async () => {
  for (const [l, desc, help] of [['fr', 'Appareils du LAN', /anciens noms acceptés : \/reseau, \/appareil, \/connu/], ['en', 'LAN devices', /old names still accepted: \/reseau, \/appareil, \/connu/]]) {
    setLocale(l)
    try {
      const b = bench()
      b.bot.start()
      b.bot.stop()
      const menu = b.commands()
      assert.deepEqual(menu.map(c => c.command), COMMAND_NAMES)
      assert.ok(!menu.some(c => Object.hasOwn(FRENCH_COMMANDS, c.command)), 'no old name in the menu')
      assert.equal(menu.find(c => c.command === 'network').description, desc)
      const h = await b.say('/help')
      assert.match(h, /\/network — /)
      assert.match(h, /\/device &lt;/)
      assert.match(h, /\/known &lt;/)
      assert.match(h, help)
    } finally {
      setLocale('fr')
    }
  }
})
